    weight: 0.6,
    // the songs run from 92 to 172; the base stays in the middle
    bpm: [92, 128],
    swing: 0,
    // his sixteenths are one hand's, "a lot smoother" than hand to hand, as he says in his 1988 video
    oneHandHats: true,
