    backbeats: [4, 12],
    backbeatLane: 'hf',
    targetDensity: 6,
    hatDepth: 0.85,
    midFills: 0.2,
    anticipate: 0.15,
    // "well-executed ruffs, triplets, short rolls on a tightly tuned snare" (Korall); stick shots on Two Not One
    rimshot: 0.15,
    drag: 0.15,
    buzz: 0.2,
    // "You can assume that he's feathering the bass drum throughout" (Bishop, Swing to Bop)
    kickFeather: 0.25,
